effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _SourceTex_TexelSize (1.0 / vec2(textureSize(inputImg, 0)))
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
vec4 u_xlat3;
vec3 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat6;
vec4 u_xlat7;
vec3 u_xlat8;
vec4 u_xlat9;
vec3 u_xlat10;
vec4 u_xlat11;
vec3 u_xlat12;
float u_xlat14;
float u_xlat39;
void main()
{
    u_xlat0.xy = (-_SourceTex_TexelSize.xy) * vec2(0.0, 0.899999976) + acScreenNorm.xy;
    u_xlat0.xyz = texture(inputImg, u_xlat0.xy).xyz;
    u_xlat1 = _SourceTex_TexelSize.xyxy * vec4(-0.899999976, -0.899999976, 0.899999976, -0.899999976) + acScreenNorm.xyxy;
    u_xlat2.xyz = texture(inputImg, u_xlat1.xy).xyz;
    u_xlat1.xyz = texture(inputImg, u_xlat1.zw).xyz;
    u_xlat3.xy = (-_SourceTex_TexelSize.xy) * vec2(0.899999976, 0.0) + acScreenNorm.xy;
    u_xlat3.xyz = texture(inputImg, u_xlat3.xy).xyz;
    u_xlat4.xyz = texture(inputImg, acScreenNorm.xy).xyz;
    u_xlat5.xyz = u_xlat3.xyz + u_xlat4.xyz;
    u_xlat2.xyz = u_xlat2.xyz + u_xlat5.xyz;
    u_xlat2.xyz = u_xlat0.xyz + u_xlat2.xyz;
    u_xlat5 = _SourceTex_TexelSize.xyxy * vec4(0.899999976, 0.899999976, -1.45000005, 0.449999988) + acScreenNorm.xyxy;
    u_xlat6.xyz = texture(inputImg, u_xlat5.xy).xyz;
    u_xlat5.xyz = texture(inputImg, u_xlat5.zw).xyz;
    u_xlat7 = _SourceTex_TexelSize.xyxy * vec4(-0.899999976, 0.899999976, 0.0, 0.899999976) + acScreenNorm.xyxy;
    u_xlat8.xyz = texture(inputImg, u_xlat7.zw).xyz;
    u_xlat7.xyz = texture(inputImg, u_xlat7.xy).xyz;
    u_xlat7.xyz = u_xlat8.xyz + u_xlat7.xyz;
    u_xlat6.xyz = u_xlat6.xyz + u_xlat8.xyz;
    u_xlat6.xyz = u_xlat4.xyz + u_xlat6.xyz;
    u_xlat3.xyz = u_xlat3.xyz + u_xlat7.xyz;
    u_xlat3.xyz = u_xlat4.xyz + u_xlat3.xyz;
    u_xlat3.xyz = u_xlat3.xyz * vec3(0.0208333004, 0.0208333004, 0.0208333004);
    u_xlat7 = _SourceTex_TexelSize.xyxy * vec4(1.45000005, 0.449999988, 0.899999976, 0.0) + acScreenNorm.xyxy;
    u_xlat8.xyz = texture(inputImg, u_xlat7.zw).xyz;
    u_xlat7.xyz = texture(inputImg, u_xlat7.xy).xyz;
    u_xlat6.xyz = u_xlat6.xyz + u_xlat8.xyz;
    u_xlat4.xyz = u_xlat4.xyz + u_xlat8.xyz;
    u_xlat0.xyz = u_xlat0.xyz + u_xlat4.xyz;
    u_xlat0.xyz = u_xlat1.xyz + u_xlat0.xyz;
    u_xlat1 = _SourceTex_TexelSize.xyxy * vec4(-0.449999988, 0.449999988, 0.449999988, 0.449999988) + acScreenNorm.xyxy;
    u_xlat4.xyz = texture(inputImg, u_xlat1.xy).xyz;
    u_xlat1.xyz = texture(inputImg, u_xlat1.zw).xyz;
    u_xlat8.xyz = u_xlat1.xyz + u_xlat4.xyz;
    u_xlat9 = _SourceTex_TexelSize.xyxy * vec4(-1.45000005, -0.449999988, -0.449999988, -0.449999988) + acScreenNorm.xyxy;
    u_xlat10.xyz = texture(inputImg, u_xlat9.zw).xyz;
    u_xlat9.xyz = texture(inputImg, u_xlat9.xy).xyz;
    u_xlat8.xyz = u_xlat8.xyz + u_xlat10.xyz;
    u_xlat11 = _SourceTex_TexelSize.xyxy * vec4(0.449999988, -0.449999988, 1.45000005, -0.449999988) + acScreenNorm.xyxy;
    u_xlat12.xyz = texture(inputImg, u_xlat11.xy).xyz;
    u_xlat11.xyz = texture(inputImg, u_xlat11.zw).xyz;
    u_xlat8.xyz = u_xlat8.xyz + u_xlat12.xyz;
    u_xlat3.xyz = u_xlat8.xyz * vec3(0.0833332986, 0.0833332986, 0.0833332986) + u_xlat3.xyz;
    u_xlat3.xyz = u_xlat6.xyz * vec3(0.0208333004, 0.0208333004, 0.0208333004) + u_xlat3.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vec3(0.0208333004, 0.0208333004, 0.0208333004) + u_xlat3.xyz;
    u_xlat0.xyz = u_xlat0.xyz * vec3(0.0208333004, 0.0208333004, 0.0208333004) + u_xlat2.xyz;
    u_xlat2 = _SourceTex_TexelSize.xyxy * vec4(-1.45000005, 1.45000005, -0.449999988, 1.45000005) + acScreenNorm.xyxy;
    u_xlat3.xyz = texture(inputImg, u_xlat2.xy).xyz;
    u_xlat2.xyz = texture(inputImg, u_xlat2.zw).xyz;
    u_xlat3.xyz = u_xlat2.xyz + u_xlat3.xyz;
    u_xlat3.xyz = u_xlat5.xyz + u_xlat3.xyz;
    u_xlat5.xyz = u_xlat4.xyz + u_xlat5.xyz;
    u_xlat5.xyz = u_xlat9.xyz + u_xlat5.xyz;
    u_xlat6.xyz = u_xlat10.xyz + u_xlat9.xyz;
    u_xlat5.xyz = u_xlat10.xyz + u_xlat5.xyz;
    u_xlat9.xyz = u_xlat10.xyz + u_xlat12.xyz;
    u_xlat3.xyz = u_xlat4.xyz + u_xlat3.xyz;
    u_xlat0.xyz = u_xlat3.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat3 = _SourceTex_TexelSize.xyxy * vec4(0.449999988, 1.45000005, 1.45000005, 1.45000005) + acScreenNorm.xyxy;
    u_xlat10.xyz = texture(inputImg, u_xlat3.xy).xyz;
    u_xlat3.xyz = texture(inputImg, u_xlat3.zw).xyz;
    u_xlat3.xyz = u_xlat3.xyz + u_xlat10.xyz;
    u_xlat2.xyz = u_xlat2.xyz + u_xlat10.xyz;
    u_xlat2.xyz = u_xlat4.xyz + u_xlat2.xyz;
    u_xlat2.xyz = u_xlat1.xyz + u_xlat2.xyz;
    u_xlat0.xyz = u_xlat2.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat2.xyz = u_xlat1.xyz + u_xlat3.xyz;
    u_xlat1.xyz = u_xlat7.xyz + u_xlat1.xyz;
    u_xlat2.xyz = u_xlat7.xyz + u_xlat2.xyz;
    u_xlat0.xyz = u_xlat2.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat0.xyz = u_xlat5.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat0.xyz = u_xlat8.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat1.xyz = u_xlat12.xyz + u_xlat1.xyz;
    u_xlat2.xyz = u_xlat11.xyz + u_xlat12.xyz;
    u_xlat1.xyz = u_xlat11.xyz + u_xlat1.xyz;
    u_xlat0.xyz = u_xlat1.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat1 = _SourceTex_TexelSize.xyxy * vec4(-1.45000005, -1.45000005, -0.449999988, -1.45000005) + acScreenNorm.xyxy;
    u_xlat3.xyz = texture(inputImg, u_xlat1.xy).xyz;
    u_xlat1.xyz = texture(inputImg, u_xlat1.zw).xyz;
    u_xlat3.xyz = u_xlat3.xyz + u_xlat6.xyz;
    u_xlat3.xyz = u_xlat1.xyz + u_xlat3.xyz;
    u_xlat1.xyz = u_xlat1.xyz + u_xlat9.xyz;
    u_xlat0.xyz = u_xlat3.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat3 = _SourceTex_TexelSize.xyxy * vec4(0.449999988, -1.45000005, 1.45000005, -1.45000005) + acScreenNorm.xyxy;
    u_xlat4.xyz = texture(inputImg, u_xlat3.xy).xyz;
    u_xlat3.xyz = texture(inputImg, u_xlat3.zw).xyz;
    u_xlat1.xyz = u_xlat1.xyz + u_xlat4.xyz;
    u_xlat2.xyz = u_xlat2.xyz + u_xlat4.xyz;
    u_xlat2.xyz = u_xlat3.xyz + u_xlat2.xyz;
    u_xlat0.xyz = u_xlat1.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat0.xyz = u_xlat2.xyz * vec3(0.00923329964, 0.00923329964, 0.00923329964) + u_xlat0.xyz;
    u_xlat39 = dot(u_xlat0.xyz, u_xlat0.xyz);
    u_xlat39 = inversesqrt(u_xlat39);
    u_xlat1.xyz = vec3(u_xlat39) * u_xlat0.xyz;
    u_xlat0.xyz = max(u_xlat0.xyz, vec3(0.0, 0.0, 0.0));
    u_xlat1.xyz = u_xlat1.xyz * _BloomThreshold.yyy;
    u_xlat0.xyz = min(u_xlat0.xyz, u_xlat1.xyz);
    u_xlat0.xyz = u_xlat0.xyz * vec3(0.908999979, 0.908999979, 0.908999979);
    u_xlat39 = max(u_xlat0.z, u_xlat0.y);
    u_xlat39 = max(u_xlat39, u_xlat0.x);
    u_xlat1.x = u_xlat39 + (-_BloomThreshold.x);
    u_xlat39 = max(u_xlat39, 9.99999975e-05);
    u_xlat14 = u_xlat1.x + 9.99999975e-05;
    u_xlat14 = max(u_xlat14, 0.0);
    u_xlat14 = min(u_xlat14, 0.000199999995);
    u_xlat14 = u_xlat14 * u_xlat14;
    u_xlat14 = u_xlat14 * 2000.00012;
    u_xlat1.x = max(u_xlat1.x, u_xlat14);
    u_xlat0.xyz = u_xlat0.xyz * u_xlat1.xxx;
    u_xlat0.xyz = u_xlat0.xyz / vec3(u_xlat39);
    u_xlat0.xyz = max(u_xlat0.xyz, vec3(0.0, 0.0, 0.0));
    u_xlat0.w = 1.0;
    fragColor = u_xlat0 * _glow_color;
    return;
}
